/* @lc app=leetcode id=2865 lang=kotlin */
class Solution { fun maximumSumOfHeights(maxHeights: List<Int>): Long = maxHeights.size.let { n -> LongArray(n).also { l -> java.util.ArrayDeque<Int>().also { s -> (0 until n).forEach { i -> (generateSequence { s.peek() }.takeWhile { it != null && maxHeights[it] >= maxHeights[i] }.forEach { s.pop() }).run { l[i] = (if (s.isEmpty()) (i + 1L) * maxHeights[i] else l[s.peek()!!] + (i - s.peek()!!.toLong()) * maxHeights[i]).also { s.push(i) } } } } }.let { l -> LongArray(n).also { r -> java.util.ArrayDeque<Int>().also { s -> (n - 1 downTo 0).forEach { i -> (generateSequence { s.peek() }.takeWhile { it != null && maxHeights[it] >= maxHeights[i] }.forEach { s.pop() }).run { r[i] = (if (s.isEmpty()) (n - i).toLong() * maxHeights[i] else r[s.peek()!!] + (s.peek()!! - i).toLong() * maxHeights[i]).also { s.push(i) } } } } }.let { r -> (0 until n).maxOf { l[it] + r[it] - maxHeights[it] } } } } }